#!/usr/bin/env node
/**
 * Generates packages/types/generated/*.d.ts: TypeScript declarations of the site's shared data
 * shapes, for JSDoc to import (`@typedef {import('../../packages/types/index.js').Council} Council`).
 * Dependency-free: a small JSON Schema (draft-07, the subset the repository's schemas use) to
 * TypeScript converter.
 *
 * Sources (each generated file names its own):
 *   - data/schemas/*.schema.json          the facts files (offices, tenures, affiliations, ...)
 *   - packages/registries/schemas/*.schema.json    the registries (councils, parties, statuses, ...)
 *   - packages/api/src/v1/contracts/v1.js  the /api/v1 answer contracts (CONTRACTS)
 *   - packages/schema/src/schema.mjs      the records database tables (TABLES)
 *
 *   node packages/types/src/generate.mjs           write the files
 *   node packages/types/src/generate.mjs --check   exit 1 when a file differs from its sources
 *
 * tests/unit/types-package.test.mjs runs the --check comparison, so the declarations cannot
 * drift from their sources. Hand-written shapes live in packages/types/hand/ and are never
 * touched here.
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const PACKAGE_DIR = path.resolve(HERE, '..');
export const REPO_ROOT = path.resolve(PACKAGE_DIR, '..', '..');
export const OUT_DIR = path.join(PACKAGE_DIR, 'generated');

/** The schema folders: [source folder, output subfolder, root-type suffix]. */
export const SCHEMA_SETS = /** @type {const} */ ([
  ['data/schemas', 'facts', 'Document'],
  ['packages/registries/schemas', 'registries', 'Registry'],
]);

const BANNER = (sources) => [
  '// GENERATED by packages/types/src/generate.mjs: do not edit. Regenerate with',
  '// `npm run build:types`; tests/unit/types-package.test.mjs fails when this file is stale.',
  `// Source: ${sources}`,
  '',
].join('\n');

// ---------------------------------------------------------------- naming

/** @param {string} s */
export const pascal = (s) => s
  .replace(/\.schema\.json$|\.json$/, '')
  .split(/[^A-Za-z0-9]+/)
  .filter(Boolean)
  .map((w) => w[0].toUpperCase() + w.slice(1))
  .join('')
  .replace(/^(\d)/, '_$1');

const IDENT = /^[A-Za-z_$][A-Za-z0-9_$]*$/;
/** @param {string} k */
const key = (k) => (IDENT.test(k) ? k : JSON.stringify(k));

/** @param {string | undefined} text @param {string} pad */
function doc(text, pad) {
  if (!text) return '';
  const lines = String(text).replace(/\*\//g, '*\\/').split('\n');
  if (lines.length === 1) return `${pad}/** ${lines[0]} */\n`;
  return `${pad}/**\n${lines.map((l) => `${pad} * ${l}`.trimEnd()).join('\n')}\n${pad} */\n`;
}

// ---------------------------------------------------------------- JSON Schema -> TypeScript

/**
 * @typedef {object} Ctx
 * @property {string} file              the schema's file name (for its own $refs)
 * @property {(file: string) => string} rootOf   a sibling schema file -> its root type name
 * @property {(file: string) => string} importPath  a sibling schema file -> the import path of its declarations
 * @property {boolean} [strictObjects]  true: an object without additionalProperties gets no index signature
 */

/**
 * A JSON Schema node as the schema files write it: a boolean schema, or an object of keywords
 * (the ones this generator reads are listed; the others are kept and ignored).
 * @typedef {boolean | JsonSchemaObject} JsonSchema
 */
/**
 * @typedef {object} JsonSchemaObject
 * @property {string} [$ref]
 * @property {unknown} [const]
 * @property {unknown[]} [enum]
 * @property {string | string[]} [type]
 * @property {Record<string, JsonSchema>} [properties]
 * @property {JsonSchema | JsonSchema[]} [items]
 * @property {JsonSchema} [additionalProperties]
 * @property {string[]} [required]
 * @property {JsonSchema[]} [oneOf]
 * @property {JsonSchema[]} [anyOf]
 * @property {JsonSchema[]} [allOf]
 * @property {string} [description]
 * @property {string} [title]
 */

const SHAPE_KEYS = ['type', 'properties', '$ref', 'enum', 'const', 'items', 'additionalProperties', 'oneOf', 'anyOf', 'allOf'];
/** Does a sub-schema say anything about shape, or only add constraints (required, if/then, pattern)? */
function shapeBearing(s) {
  if (s === true || s === false) return true;
  if (!s || typeof s !== 'object') return false;
  if (SHAPE_KEYS.some((k) => k in s && !['oneOf', 'anyOf', 'allOf'].includes(k))) return true;
  return ['oneOf', 'anyOf', 'allOf'].some((k) => Array.isArray(s[k]) && s[k].some(shapeBearing));
}

/** @param {string} ref @param {Ctx} ctx */
function refType(ref, ctx) {
  const [file, pointer = ''] = ref.split('#');
  const def = pointer.match(/^\/(?:\$defs|definitions)\/(.+)$/);
  if (!file) {
    if (def) return pascal(def[1]);
    if (pointer === '' || pointer === '/') return ctx.rootOf(ctx.file);
    throw new Error(`${ctx.file}: unsupported $ref ${ref}`);
  }
  const base = `import('${ctx.importPath(file)}')`;
  if (def) return `${base}.${pascal(def[1])}`;
  return `${base}.${ctx.rootOf(file)}`;
}

/** @param {unknown[]} parts */
const union = (parts) => {
  const uniq = [...new Set(parts)];
  if (uniq.includes('unknown')) return 'unknown';
  return uniq.length === 1 ? String(uniq[0]) : uniq.map((p) => (/[|&]/.test(String(p)) && !/^[({[]/.test(String(p)) ? `(${p})` : p)).join(' | ');
};
const paren = (t) => (/[|&]/.test(t) && !/^\(.*\)$/.test(t) ? `(${t})` : t);

/**
 * A JSON Schema as a TypeScript type expression.
 * @param {JsonSchema | null | undefined} s @param {Ctx} ctx @param {string} pad
 * @returns {string}
 */
export function toTs(s, ctx, pad = '') {
  if (s === true || s === undefined || s === null || (s && typeof s === 'object' && Object.keys(s).length === 0)) return 'unknown';
  if (s === false) return 'never';
  if ('$ref' in s) return refType(s.$ref, ctx);
  if ('const' in s) return JSON.stringify(s.const);
  if (Array.isArray(s.enum)) return union(s.enum.map((v) => JSON.stringify(v)));

  /** @type {string[]} */
  const parts = [];
  if (Array.isArray(s.type)) {
    parts.push(union(s.type.map((t) => toTs({ ...s, type: t, oneOf: undefined, anyOf: undefined, allOf: undefined }, ctx, pad))));
  } else if (s.type || s.properties || s.items || s.additionalProperties !== undefined) {
    parts.push(single(s, ctx, pad));
  }
  for (const k of ['oneOf', 'anyOf']) {
    const branches = (s[k] || []).filter(shapeBearing);
    if (branches.length) parts.push(paren(union(branches.map((b) => toTs(b, ctx, pad)))));
  }
  for (const b of (s.allOf || []).filter(shapeBearing)) parts.push(paren(toTs(b, ctx, pad)));
  if (!parts.length) return 'unknown';
  return parts.length === 1 ? parts[0] : parts.join(' & ');
}

/** One `type` (a string), with that type's keywords. @param {JsonSchemaObject} s @param {Ctx} ctx @param {string} pad */
function single(s, ctx, pad) {
  const type = s.type || (s.properties || s.additionalProperties !== undefined ? 'object' : s.items ? 'array' : undefined);
  switch (type) {
    case 'string': return 'string';
    case 'number': case 'integer': return 'number';
    case 'boolean': return 'boolean';
    case 'null': return 'null';
    case 'array': {
      if (Array.isArray(s.items)) return `[${s.items.map((i) => toTs(i, ctx, pad)).join(', ')}]`;
      if (s.items === undefined) return 'unknown[]';
      const t = toTs(s.items, ctx, pad);
      return /[|&]/.test(t) && !/^\(.*\)$/.test(t) ? `Array<${t}>` : `${t}[]`;
    }
    case 'object': return objectType(s, ctx, pad);
    default: return 'unknown';
  }
}

/** @param {JsonSchemaObject} s @param {Ctx} ctx @param {string} pad */
function objectType(s, ctx, pad) {
  const inner = `${pad}  `;
  const required = new Set(s.required || []);
  const props = Object.entries(s.properties || {});
  const extra = s.additionalProperties;
  /** @type {string[]} */
  const lines = [];
  for (const [name, sub] of props) {
    const comment = sub && typeof sub === 'object' ? (sub.description || sub.title) : undefined;
    lines.push(`${doc(comment, inner)}${inner}${key(name)}${required.has(name) ? '' : '?'}: ${toTs(sub, ctx, inner)};`);
  }
  // Required names with no property schema still exist.
  const extraType = extra && typeof extra === 'object' && Object.keys(extra).length ? toTs(extra, ctx, inner) : 'unknown';
  for (const name of required) if (!(s.properties && name in s.properties)) lines.push(`${inner}${key(name)}: ${extraType};`);
  if (extra === false) {
    // closed object: no index signature
  } else if (extra && typeof extra === 'object' && Object.keys(extra).length) {
    const t = toTs(extra, ctx, inner);
    lines.push(`${inner}[key: string]: ${props.length ? 'unknown' : t};`);
  } else if (!ctx.strictObjects || extra === true || (extra && typeof extra === 'object')) {
    lines.push(`${inner}[key: string]: unknown;`);
  }
  if (!lines.length) return '{}';
  return `{\n${lines.join('\n')}\n${pad}}`;
}

// ---------------------------------------------------------------- the generated files

/** @param {string} t a type expression @returns {boolean} can it be an interface body? */
const isObjectLiteral = (t) => t.startsWith('{\n') && t.endsWith('}') && !/\n\} [|&] /.test(t);

/** @param {string} name @param {string} t @param {string} [comment] */
const decl = (name, t, comment) => `${doc(comment, '')}${isObjectLiteral(t) ? `export interface ${name} ${t}` : `export type ${name} = ${t};`}\n`;

/** Every schema file name -> its output subfolder and root type (a $ref may cross folders). */
const fileIndex = () => new Map(SCHEMA_SETS.flatMap(([dir, sub, suffix]) => readdirSync(path.join(REPO_ROOT, dir))
  .filter((f) => f.endsWith('.schema.json'))
  .map((f) => [f, { sub, root: pascal(f) + suffix }])));

/** One schema folder: one .d.ts per schema, root type plus one export per $defs entry. */
function schemaSet([dir, sub, suffix]) {
  const abs = path.join(REPO_ROOT, dir);
  const files = readdirSync(abs).filter((f) => f.endsWith('.schema.json')).sort();
  const index = fileIndex();
  const local = (file) => files.includes(file);
  const rootOf = (file) => (local(file) ? pascal(file) + suffix : index.get(file)?.root ?? pascal(file) + suffix);
  /** A schema file -> the import path of its declarations from this set's folder. */
  const importPath = (file) => {
    const target = local(file) ? sub : index.get(file)?.sub;
    if (!target) throw new Error(`${dir}: $ref to unknown schema ${file}`);
    const rel = path.posix.relative(sub, target);
    return `${rel ? rel : '.'}/${file.replace(/\.schema\.json$/, '.js')}`;
  };
  /** @type {Record<string, string>} */
  const out = {};
  for (const file of files) {
    const schema = JSON.parse(readFileSync(path.join(abs, file), 'utf8'));
    /** @type {Ctx} */
    const ctx = { file, rootOf, importPath };
    let text = BANNER(`${dir}/${file}`);
    text += `\n${decl(rootOf(file), toTs(schema, ctx), schema.title ? `${schema.title}${schema.description ? `\n\n${schema.description}` : ''}` : undefined)}`;
    for (const [name, def] of Object.entries(schema.$defs || schema.definitions || {})) {
      text += `\n${decl(pascal(name), toTs(def, ctx), def.description || def.title)}`;
    }
    out[`${sub}/${file.replace(/\.schema\.json$/, '.d.ts')}`] = text;
  }
  return out;
}

/** The records database: one row interface per table, and the table map. */
async function recordsTables() {
  const { TABLES } = await import(pathToFileURL(path.join(REPO_ROOT, 'packages/schema/src/schema.mjs')).href);
  const TS = { TEXT: 'string', INTEGER: 'number', REAL: 'number' };
  let text = BANNER('packages/schema/src/schema.mjs (TABLES)');
  text += '\n// A row as SQLite and D1 return it. TEXT columns that hold JSON (meta, record, card, body,\n// value, payload) are the stored text: parse them to get the record. Nullable columns are\n// `| null`. The table map Tables names each row type by its table.\n';
  const names = [];
  for (const t of TABLES) {
    const name = `${pascal(t.name)}Row`;
    names.push([t.name, name]);
    const comment = [`Table \`${t.name}\` (group ${t.group}; primary key ${t.pk.join(', ')}; ordered by ${t.order}).`, t.note].filter(Boolean).join('\n');
    const cols = t.columns.map((c) => `  ${key(c.name)}: ${TS[c.type] || 'unknown'}${c.notNull ? '' : ' | null'};`).join('\n');
    text += `\n${doc(comment, '')}export interface ${name} {\n${cols}\n}\n`;
  }
  text += `\nexport interface Tables {\n${names.map(([t, n]) => `  ${key(t)}: ${n};`).join('\n')}\n}\n`;
  text += '\nexport type TableName = keyof Tables;\n';
  return { 'records-db.d.ts': text };
}

/** /api/v1: one type per route and variant, its error answer, and the route map. */
async function apiContracts() {
  const { CONTRACTS } = await import(pathToFileURL(path.join(REPO_ROOT, 'packages/api/src/v1/contracts/v1.js')).href);
  /** @type {Ctx} */
  const ctx = { file: 'v1.js', rootOf: () => 'unknown', importPath: () => { throw new Error('v1.js: a contract has no file $ref'); } };
  let text = BANNER('packages/api/src/v1/contracts/v1.js (CONTRACTS)');
  text += '\n// The fields a contract names in `required` are promised; others may come and go, so every\n// object keeps an index signature (a client ignores fields it does not know).\n';
  const routes = [];
  for (const [route, contract] of Object.entries(CONTRACTS)) {
    const base = pascal(route);
    const variants = [];
    for (const v of contract.variants) {
      const name = `${base}${pascal(v.name)}Answer`;
      variants.push([v.name, name]);
      const when = Object.entries(v.when).map(([k, val]) => `${k}=${val === '*' ? '<given>' : val === '' ? '<absent>' : val}`).join(' ');
      text += `\n${decl(name, toTs(v.schema, ctx), `GET /api/v1/${route} (${when}): ${v.summary}`)}`;
    }
    const errName = `${base}ErrorAnswer`;
    text += `\n${decl(errName, toTs(contract.errors, ctx), `/api/v1/${route}: its JSON error answers (4xx and 5xx).`)}`;
    routes.push([route, variants, errName]);
  }
  text += `\n/** Every v1 route: its variants by name, and its error answer. */\nexport interface V1Routes {\n${routes.map(([r, vs, e]) => `  ${key(r)}: {\n    variants: {\n${vs.map(([n, t]) => `      ${key(n)}: ${t};`).join('\n')}\n    };\n    error: ${e};\n  };`).join('\n')}\n}\n`;
  text += '\nexport type V1Route = keyof V1Routes;\n/** The answer of one route and variant. */\nexport type V1Answer<R extends V1Route, V extends keyof V1Routes[R][\'variants\']> = V1Routes[R][\'variants\'][V];\n';
  return { 'api-v1.d.ts': text };
}

/** Every generated file: relative path under generated/ -> text. */
export async function generate() {
  /** @type {Record<string, string>} */
  const files = {};
  for (const set of SCHEMA_SETS) Object.assign(files, schemaSet(set));
  Object.assign(files, await recordsTables(), await apiContracts());
  return files;
}

/** The generated files that differ from what is on disk (missing, stale, or no longer generated). */
export async function staleFiles() {
  const files = await generate();
  const stale = [];
  for (const [rel, text] of Object.entries(files)) {
    const file = path.join(OUT_DIR, rel);
    if (!existsSync(file) || readFileSync(file, 'utf8').replace(/\r\n/g, '\n') !== text) stale.push(rel);
  }
  const walk = (dir, pre = '') => readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(dir, e.name), `${pre}${e.name}/`) : [`${pre}${e.name}`]));
  if (existsSync(OUT_DIR)) for (const rel of walk(OUT_DIR)) if (!(rel in files)) stale.push(`${rel} (no longer generated)`);
  return stale;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const stale = await staleFiles();
    if (stale.length) {
      console.error(`packages/types: ${stale.length} generated file(s) out of date:\n  ${stale.join('\n  ')}\nRun npm run build:types.`);
      process.exit(1);
    }
    console.log('packages/types: generated declarations up to date');
  } else {
    const files = await generate();
    for (const [rel, text] of Object.entries(files)) {
      const file = path.join(OUT_DIR, rel);
      mkdirSync(path.dirname(file), { recursive: true });
      writeFileSync(file, text);
    }
    console.log(`packages/types: wrote ${Object.keys(files).length} files to packages/types/generated/`);
  }
}
